architecture.h4_f:
msg = CBOR{v:1, ekiwandiiko, okuddamu_ku, okusindikibwa_ku}
ct = AES-GCM-256-Encrypt (k, nonce, obubaka, aad = ekisenge_id)
POST /api/ebisenge/{id}/obubaka {ekiwandiiko ekikusike: hex (ct), nonce: hex}

cryptoWire.h5_f:
ebweru = CBOR{
  ensibuko_ennyingo: hex32, .
  ekigendererwa_omukozesa: int64, .
  ekiwandiiko_eky'omunda: bytes, .
  munda_nonce: bytes, .
  esindikiddwa_ku: unix_ms
}
sig = Ed25519-Sign (ensibuko_priv, ebweru)
POST /federation/okutuusa { envulopu: ebweru, sig: hex64 }

auth.h1_f:
POST /api/okukakasa/okuwandiisa
  { erinnya ly'omukozesa, ekigambo ky'okuyingira, x25519_ekisumuluzo_eky'olukale, erinnya_ly'okulaga, essimu?, email?, avatar_emoji }

Okuddamu 201 Yatondebwawo:
  { access_token, refresh_token, id_omukozesa, erinnya ly'omukozesa, ... }

auth.h3_f:
access_token omugugu gw'omugaso:
  { sub: id_omukozesa, jti: ekyuma_id, typ: "okutuuka", exp: kati + 15min }
refresh_token omugugu gw'omugaso:
  { sub: user_id, jti: device_id, typ: "okuzza obuggya", exp: kati + 30d }

HS256-essiddwaako omukono n'ekyama kya node ekya 64-byte okuva ku .env

auth.h4_f:
register_begin (): okusoomoozebwa = rand (32) .
                    ebyokulonda = { rp.id, omukozesa.id, pubKeyCredParams, okusoomoozebwa }
                    okuddamu okulonda

register_finish (okukakasa):
  okukakasa okukakasa ku TPM / Secure Enclave root CA .
  store { credential_id, ekisumuluzo_eky'olukale, okubala: 0 }

auth.h7_f:
POST /api/okukakasa/qr/okutandika
  → { nonce: Hex ya bit 128, ttl: 60 }
QR payload = { nonce, id_omukozesa, seva: "https://node.ekyokulabirako" }

POST /api/okukakasa/qr/okukakasa { nonce }
  → ekyuma ekipya ekiwandiisiddwa; Aba JWT bakomawo.

rooms.h6_f:
sender_pseudo = HMAC-SHA256 (ekisenge_omunnyo_ogw'obulimba, omusindika_id) [:16] // 32 hex
ciphertext = AES-GCM-Encrypt (ekisenge_ekisumuluzo, nonce, CBOR_payload, aad = ekisenge_id)

Fan-out frame: { ekika:"m", ekisenge, msg:{id, ct, nonce, omusindika_pseudo, yasindikibwa_ku} }

files.h2_f:
init POST /api/fayiro/eziddamu/init {erinnya lya fayiro, obunene, ekitundu_obunene_obubaka}
            ← {upload_id, sayizi_y'ekitundu}
chunk PUT /api/fayiro/eziddamu okukozesebwa/{upload_id}/chunk/{offset} <ct bytes>
            ← 204. Ekitabo
okumaliriza POST /api/fayiro/okuddamu okukola/{upload_id}/okumaliriza {plain_blake3}
            ← 201 {fayiro_id, url}
TTL ku bitawedde: 24 h

files.h4_f:
olukalala_olw'okugaana = {
  "okukozesa/x-dosexec",
  "okukozesa/x-sharedlib",
  "okukozesa/x-mach-binary",
}
singa magic.from_buffer (buf [: 1024]) mu deny_list: zzaayo 415

presence.h1_f:
kasitoma: ku kusooka okukuba ekisumuluzo → sindika {type:"t", state:"start"}
         tewakyali kusindika okumala s 3 okuggyako nga embeera ekyuse
         s 10 oluvannyuma lw'okukuba ekisumuluzo ekisembayo → sindika {type:"t", state:"stop"}
receiver: auto-stop 10 s oluvannyuma lw'okusembayo "okutandika" singa tewali "stop" etuuse

presence.h2_f:
POST /api/ebisenge/{id}/soma { id_obubaka_busembayo_okusoma }

singa omukozesa.hides_receipts:
   temugumiikiriza; toweereza ku mpewo
   toweereza lisiiti z'abalala eri omukozesa ono
else:
   UPSERT okusoma_lisiiti VALUES (ekisenge_id, omukozesa_id, obubaka_id, NOW())
   okuweereza ku mpewo {ekika:"r", ekisenge, omukozesa, message_id}

calls.h1_f:
POST /api/okuyita/{room_id}/tandika {vidiyo, amaloboozi} → call_id
WS okuweereza ku mpewo {ekika:"c", ekika:"okuyita", call_id}
WS okuweereza ku mpewo {ekika:"c", ekika:"okuwaayo", sdp}
WS okuweereza ku mpewo {ekika:"c", ekika:"okuddamu", sdp}
WS okuweereza ku mpewo {ekika:"c", ekika:"omuntu eyeesimbyewo",ice} × N
POST /api/okuyita/{okuyita_id}/okuggwaako

gossip.h3_f:
okulanga = {pubkey, enkomerero, okulanga_ku}
sig = Ed25519-Omukono (pubkey_priv, CBOR (okulanga))
olugambo payload: [..., {okulanga, akabonero}, ...]

receiver: kakasa sig against ad.pubkey → tereka iff ok
okugatta ku: PoW ya 2^18 ziro ezikulembera ku {pubkey, endpoint}

stealth.h2_f:
KasitomaMbalamusizza bytes = chrome_120_template ne {
  random = random yaffe, .
  server_name = erinnya lyaffe ery'omukozi (oba ECH-ezingiddwa), .
  session_id = id yaffe ey'olutuula, .
}
JA4 = t13d_xxxx_xxxx_xxxx (ekwatagana ne Chrome stable eriwo kati)

stealth.h4_f:
DoH: POST https://ekire-dns.com/dns-okubuuza {erinnya: x.vortexx.sol}
ECH: ClientHello.extensions += encrypted_sni (ekisumuluzo_eky'olukale_okuva mu_likoda_ya HTTPS)
DGA: domain (t) = base32( SHA256(ensigo ∥ YYYY-MM-DD) )[:16] + ".ekyokulabirako".

push.h4_f:
iOS NSE: didReceive (okusaba) { decrypt (okusaba.ebirimu.amawulire g'omukozesa) }
Android FCM: onMessageReceived(Obubaka obw'ewala) { decrypt (Obubaka obw'ewala.data) }
Web SW: self.addEventListener ('okusika', e => okuggyamu (e.data))

bots.h1_f:
tonda: POST /api/bots {erinnya ly'omukozesa, erinnya_ly'okwolesebwa, koodi}
          → {bot_id, akabonero, ekisumuluzo ky'okunywa}
run: mu nkola (coroutine munda mu node) .
      OR ebweru (okulonda-okuwanvu / api / bots / {id} / okulongoosa, token-auth'd)
obubaka: {ekiwandiiko, omukono: Ed25519-Omukono (bot_priv, canonical_msg)}

bots.h2_f:
ku /tandika {
  emit "Mwaniriziddwa, {ctx.erinnya_eryasooka}".
}
ku /yongera <ekintu> {
  state.list = (state.olukalala oba []) + [ctx.args.item].
  emit "Eyongerwako: {ctx.args.item}"
}

security.h4_f:
canary.txt (buli lunaku):
  {olunaku, sig: Ed25519-Sign (okufulumya_priv, olunaku)}
kasitoma akakasa → taliiwo oba si ntuufu ⇒ okukkaanya kuteeberezebwa

mu mbeera ey’amangu:
  admin POST /api/admin/okusazaamu-byona {ensonga}
  node broadcasts {ekika:"n", ekintu:"okukkaanya", ensonga}
  bakasitoma basiimuula ebisumuluzo, bakaka okuddamu bootstrap

debugging.h2_f:
rate histograms (buli kkubo + enkola):
  vortex_http_requests_total{ekkubo,enkola,embeera}
  vortex_http_okusaba_obudde_sekondi_bucket{ekkubo,enkola,le}

ebipima ebipima websocket:
  vortex_ws_ebiyungo{node}.
  vortex_ws_fanout_obuziba_ennyiriri{ekisenge,omukozesa}

ebibala eby’ennono:
  vortex_messages_sent_omugatte {ekika_eky'ekisenge}
  vortex_okuyita_kutandika_omugatte {ekika}

