{
  "erinnya ly'omukozesa": "alice",
  "password": "ekintu ekituufu bbaatule y'embalaasi",
  "totp": "123456" // kyetaagisa singa 2FA esobozeseddwa
}

login.h4_f:
ku buwanguzi: 201 + JWT envulopu (enkula y’emu ne register)
ku 2FA yeetaagibwa: 200 { "yeetaaga_2fa": kituufu } (tewali JWT n'okutuusa kati)
ku kulemererwa: 401 { "ensobi":"ebiwandiiko_ebitali bituufu" }

apns.h1_f:
POST https://api.push.apple.com/3/ekyuma/<akabonero_aka_ekyuma>
Emitwe: apns-omulamwa: <bundle_id>, apns-push-ekika: okulabula, apns-okugwa-id: ekisenge:42
Omubiri: {aps: {okulabula: {omutwe, omubiri}}, data: <asimbiddwako akabonero>}

bmp.h1_f:
mailbox_id = HKDF (omuweereza_ekisumuluzo ky'okufulumya, info = "bmp-v1", len = 32)
Okutereka: POST /bmp/okutereka {mailbox_id, blob ≤1MB}
Okulonda: GET /bmp/obubaka (obukakafu)

controller.h1_f:
GET /v1/integrity → {embeera, essiddwako omukono, ekwatagana, etakwatagana, ...}
GET /v1/obulamu → {embeera, enkyusa, pubkey, ebibalo}
GET /v1/ebiyingizibwa → [{protocol, url}, ...]
GET /v1/endabirwamu → [omufuzi_url, ...]

fcm.h1_f:
POST https://fcm.googleapis.com/v1/pulojekiti/<pulojekiti>/obubaka:sindika
Olukusa: Omusitula <oauth2_token>
Omubiri: {obubaka: {akabonero: <ekyuma>, data: {...ekissiddwako akabonero...}, android: {ekisumuluzo_kigwa}}}

federation.h1_f:
envulopu = {ensibuko_node, target_omukozesa, munda_ct, munda_nonce, sent_ku}
sig = Ed25519-Omukono (ensibuko_priv, CBOR (envulopu))
POST /federation/okutuusa {envulopu, sig}
B akakasa: akabonero ku federations [source_node].pubkey

fts5.h1_f:
CREATE VIRTUAL TABLE obubaka_fts USING fts5(
  ebirimu, -- ennyiriri eziriko akabonero
  ekisenge_id UNINDEXED, .
  tokenize = 'unicode61 okuggyawo_ebigambo 2'.
);
okubuuza: SELECT rowid FROM obubaka_fts WHERE ebirimu MATCH 'foo'.

gravitix.h1_f:
on /start { emit "Mwaniriziddwa, {ctx.erinnya_eryasooka}" }
ku /yongera <ekintu> {
  state.list = (state.olukalala oba []) + [ctx.args.item].
  emit "Eyongerwako: {ctx.args.item}"
}

vapid.h1_f:
VAPID ebisumuluzo: Ed25519 ebisumuluzo bibiri buli node
akabonero JWT: {aud: push_service_ensibuko, exp: kati + 12h, sub: mailto:ops@ekyokulabirako}
emitwe gy'okusaba okusika: Olukusa: vapid t=<jwt>, k=<vapid_public_key>
